    QuoteModel(
      id: 'q101',
      authorEn: 'Marcus Aurelius', authorPt: 'Marco Aur\u00E9lio', authorEs: 'Marco Aurelio',
      textEn: 'Everything we hear is an opinion, not a fact. Everything we see is a perspective, not the truth. The universe is change; our life is what our thoughts make it.',
